import { useEffect, useState } from "react";
import axios from "axios";

export default function TeacherDashboard() {
  const [courses, setCourses] = useState([]);
  const [submissions, setSubmissions] = useState([]);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const courseRes = await axios.get("/api/teachers/1/courses");
      const subRes = await axios.get("/api/teachers/1/submissions");

      setCourses(courseRes.data);
      setSubmissions(subRes.data);
    } catch (err) {
      console.log(err);
    }
  };

  return (
    <div className="p-6 max-w-6xl">

      {/* HEADER */}
      <div className="mb-6">
        <h1 className="text-2xl font-semibold text-gray-900">
          Dr. Riya Sharma
        </h1>
        <p className="text-gray-400 text-sm">
          Teacher Dashboard
        </p>
      </div>

      {/* STATS */}
      <div className="grid grid-cols-3 gap-6 mb-8">
        <div className="bg-white p-4 rounded-lg shadow-sm border">
          <p className="text-gray-400 text-sm">My Courses</p>
          <h2 className="text-2xl font-bold">{courses.length}</h2>
        </div>

        <div className="bg-white p-4 rounded-lg shadow-sm border">
          <p className="text-gray-400 text-sm">Total Students</p>
          <h2 className="text-2xl font-bold">
            {courses.reduce((s, c) => s + (c.student_count || 0), 0)}
          </h2>
        </div>

        <div className="bg-white p-4 rounded-lg shadow-sm border">
          <p className="text-gray-400 text-sm">Submissions</p>
          <h2 className="text-2xl font-bold">{submissions.length}</h2>
        </div>
      </div>

      {/* COURSES */}
      <div className="mb-8">
        <h2 className="text-lg font-semibold mb-3">My Courses</h2>

        <div className="grid grid-cols-2 gap-4">
          {courses.map((c) => (
            <div
              key={c.course_id}
              className="bg-white p-4 rounded-lg border shadow-sm"
            >
              <h3 className="font-medium text-gray-800">
                {c.course_name}
              </h3>
              <p className="text-sm text-gray-400">
                {c.student_count} students
              </p>
            </div>
          ))}
        </div>
      </div>

      {/* SUBMISSIONS */}
      <div>
        <h2 className="text-lg font-semibold mb-3">
          Recent Submissions
        </h2>

        {submissions.length === 0 ? (
          <p className="text-gray-400">No submissions yet</p>
        ) : (
          <div className="space-y-3">
            {submissions.slice(0, 5).map((s) => (
              <div
                key={s.submission_id}
                className="bg-white p-4 rounded-lg border shadow-sm flex justify-between items-center"
              >
                <div>
                  <p className="font-medium text-gray-800">
                    {s.student_name}
                  </p>
                  <p className="text-sm text-gray-400">
                    {s.assignment_title}
                  </p>
                </div>

                <span className="text-xs bg-gray-100 px-2 py-1 rounded">
                  Submitted
                </span>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
